// HasSocialAccount applies the HasEdge predicate on the "social_account" edge.
func HasSocialAccount() predicate.SocialTaskLog {
	return predicate.SocialTaskLog(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SocialAccountTable, SocialAccountColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSocialAccountWith applies the HasEdge predicate on the "social_account" edge with a given conditions (other predicates).
func HasSocialAccountWith(preds ...predicate.SocialAccount) predicate.SocialTaskLog {
	return predicate.SocialTaskLog(func(s *sql.Selector) {
		step := newSocialAccountStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasUser applies the HasEdge predicate on the "user" edge.
